// Attach each deck's collection (its curiosa sideboard), matched by name. Decks
// whose sideboard is empty simply have no collection.
const communityCollectionMap = communityCollections as Record<string, Record<string, number>>
export const communityDecks: DeckList[] = communityDeckList.map((d) => {
  const c = communityCollectionMap[d.name]
  return c && Object.keys(c).length ? { ...d, collection: c } : d
})
